<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Adventure Dictionary</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><style>body{background:#f2efe7}.wrap{max-width:950px;margin:auto;padding:30px 16px}.word-card{background:#fff;border-radius:14px;padding:16px;margin-bottom:10px}.score{height:7px;background:#eee;border-radius:7px}.score i{display:block;height:100%;background:#6e56b4}</style></head><body><main class="wrap"><a href="<?= base_url('belajar/english-quest'); ?>">← Peta Dunia</a><h1 class="mt-3">📖 Adventure Dictionary</h1><p>Kosakata, pelafalan, contoh penggunaan, dan tingkat penguasaanmu.</p><?php foreach($words as $w): ?><article class="word-card"><div class="d-flex justify-content-between"><div><h2><?= html_escape($w['word']); ?> <button class="btn btn-sm" onclick="speechSynthesis.speak(Object.assign(new SpeechSynthesisUtterance('<?= html_escape(addslashes($w['word'])); ?>'),{lang:'en-US',rate:.8}))">🔊</button></h2><b><?= html_escape($w['meaning']); ?></b><p class="text-secondary mb-1">Example: I can use “<?= html_escape($w['word']); ?>” in my adventure.</p></div><span><?= (int)$w['mastery_score']; ?>%</span></div><div class="score"><i style="width:<?= max(0,min(100,(int)$w['mastery_score'])); ?>%"></i></div><small>Benar <?= (int)$w['correct_count']; ?> · Salah <?= (int)$w['wrong_count']; ?></small></article><?php endforeach; ?></main></body></html>
